239:
SELECT COUNT(DISTINCT c."bond_id") AS connections_count
FROM "connected" c
WHERE c."atom_id" LIKE 'TR%\_19' ESCAPE '\';

355:
SELECT "c"."keywords"
FROM "cards" AS "c"
WHERE "c"."name" LIKE '%Angel of Mercy%';

714:
SELECT c."text"
FROM comments c
WHERE c."userdisplayname" LIKE '%Harvey Motulsky%';

745:
SELECT "p"."id"
FROM "publisher" AS "p"
WHERE "p"."publisher_name" LIKE '%Star Trek%';

803:
SELECT sp."id"
FROM "superpower" AS sp
WHERE LOWER(sp."power_name") = LOWER('cryokinesis');

747:
SELECT COUNT(*) AS total_superheroes_without_full_name
FROM "superhero" AS s
WHERE s."full_name" IS NULL;

1377:
SELECT COUNT(*) AS president_count
FROM "member" m
WHERE m."position" LIKE '%President%';
